// Получаем данные закупки от CRM
const data = $input.first().json.body || $input.first().json;

const publicationId = data.publication_id;
const purchase = data;

// Формируем данные для Фабрикант API
// TODO: заполнить после получения WSDL-схем от Фабрикант
const fabrikantPayload = {
  // Основные поля лота
  lotName: purchase.subject || 'Закупка #' + purchase.purchase_id,
  lotDescription: purchase.items?.map(i => `${i.item_name} — ${i.quantity} ${i.unit}`).join('\n') || '',
  startPrice: purchase.nmck,
  currency: 'RUB',

  // Сроки
  deliveryTerm: purchase.execution_term,

  // Организация (заполнить реквизиты)
  organizationInn: purchase.contractor?.inn || 'УКАЖИТЕ_ИНН',
  organizationOgrn: purchase.contractor?.ogrn || 'УКАЖИТЕ_ОГРН',

  // Позиции
  items: (purchase.items || []).map(item => ({
    name: item.item_name,
    quantity: item.quantity,
    unit: item.unit,
    unitPrice: item.unit_price,
  })),

  // Служебные
  _publicationId: publicationId,
  _purchaseId: purchase.purchase_id,
};

return [{ json: { publicationId, fabrikantPayload, rawData: purchase } }];

// ══════════════════════════════════════════════════════════════
// ЗАГЛУШКА: здесь будет реальный вызов Фабрикант SOAP API
// После получения credentials от Фабрикант:
//   1. Получить WSDL схемы на fabrikant.ru/integration-api
//   2. Заменить этот узел на HTTP Request с SOAP envelope
//   3. URL: https://api.fabrikant.ru/... (уточнить у Фабрикант)
//
// Пример SOAP envelope:
// <soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/">
//   <soapenv:Header>
//     <auth:Authentication>
//       <auth:Login>{{LOGIN}}</auth:Login>
//       <auth:Password>{{PASSWORD}}</auth:Password>
//     </auth:Authentication>
//   </soapenv:Header>
//   <soapenv:Body>
//     <lot:CreateLot>...(данные из предыдущего узла)...</lot:CreateLot>
//   </soapenv:Body>
// </soapenv:Envelope>
// ══════════════════════════════════════════════════════════════

const { publicationId, fabrikantPayload } = $input.first().json;

// ВРЕМЕННО: возвращаем success=false с пояснением
return [{
  json: {
    publicationId,
    success: false,
    error: 'API Фабрикант не настроен. Получите credentials на fabrikant.ru/integration-api и настройте узел «Вызов Фабрикант API».',
    fabrikantPayload,
  }
}];
